#!/usr/bin/env python3
"""ARIA - Virtual Personal Assistant  |  Run: python3 aria.py"""
import os, sys, json, sqlite3, asyncio, base64
from datetime import datetime, timedelta
from typing import Optional

missing = []
try: import anthropic
except: missing.append("anthropic")
try: import fastapi; import uvicorn
except: missing.append("fastapi uvicorn")
try: from apscheduler.schedulers.background import BackgroundScheduler
except: missing.append("apscheduler")
try: from dotenv import load_dotenv
except: missing.append("python-dotenv")

if missing:
    print("\n[ARIA] Install missing packages:\n")
    print(f"  pip3 install {' '.join(missing)}\n")
    sys.exit(1)

from dotenv import load_dotenv; load_dotenv()
from fastapi import FastAPI, WebSocket, WebSocketDisconnect
from fastapi.responses import HTMLResponse, Response
from pydantic import BaseModel
import uvicorn, anthropic

API_KEY = os.getenv("ANTHROPIC_API_KEY","")
PORT    = int(os.getenv("WEB_PORT","8000"))
HOST    = os.getenv("WEB_HOST","0.0.0.0")

if not API_KEY:
    print("\n[ARIA] Missing API key. Create a .env file with:\n  ANTHROPIC_API_KEY=your-key-here\n")
    sys.exit(1)

# ── Database ──────────────────────────────────────────────────
db = sqlite3.connect("aria.db", check_same_thread=False)
db.row_factory = sqlite3.Row
db.executescript("""
CREATE TABLE IF NOT EXISTS events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL, description TEXT,
    start_time TEXT NOT NULL, end_time TEXT,
    location TEXT, source TEXT DEFAULT 'local',
    created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL, description TEXT,
    status TEXT DEFAULT 'pending',
    priority TEXT DEFAULT 'medium',
    due_date TEXT, category TEXT,
    created_at TEXT DEFAULT (datetime('now')),
    completed_at TEXT);
CREATE TABLE IF NOT EXISTS reminders (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL, description TEXT,
    trigger_time TEXT NOT NULL,
    type TEXT DEFAULT 'reminder',
    is_active INTEGER DEFAULT 1,
    is_triggered INTEGER DEFAULT 0,
    created_at TEXT DEFAULT (datetime('now')));
""")
db.commit()

# ── Scheduler ─────────────────────────────────────────────────
scheduler = BackgroundScheduler()
scheduler.start()
active_ws: list = []

def fire_reminder(rid: int, title: str):
    db.execute("UPDATE reminders SET is_triggered=1 WHERE id=?", (rid,))
    db.commit()
    asyncio.run(_broadcast({"type":"reminder","id":rid,"title":title}))

async def _broadcast(msg: dict):
    for ws in list(active_ws):
        try: await ws.send_json(msg)
        except: pass

def schedule_reminder(rid: int, trigger_iso: str, title: str):
    t = datetime.fromisoformat(trigger_iso)
    if t <= datetime.utcnow(): return
    scheduler.add_job(fire_reminder,"date",run_date=t,id=f"r{rid}",args=[rid,title],replace_existing=True)

for row in db.execute("SELECT id,title,trigger_time FROM reminders WHERE is_active=1 AND is_triggered=0").fetchall():
    schedule_reminder(row["id"], row["trigger_time"], row["title"])

# ── AI Brain ──────────────────────────────────────────────────
SYSTEM = """You are ARIA — a friendly personal assistant.
Manage calendars, tasks, reminders. Resolve relative dates using the current datetime provided.
Be concise. Confirm actions clearly."""

TOOLS = [
    {"name":"get_current_datetime","description":"Get current date and time","input_schema":{"type":"object","properties":{}}},
    {"name":"get_upcoming_events","description":"Get upcoming events","input_schema":{"type":"object","properties":{"days":{"type":"integer","default":7}}}},
    {"name":"create_event","description":"Create calendar event","input_schema":{"type":"object","properties":{"title":{"type":"string"},"start_time":{"type":"string"},"end_time":{"type":"string"},"description":{"type":"string"},"location":{"type":"string"}},"required":["title","start_time"]}},
    {"name":"delete_event","description":"Delete event","input_schema":{"type":"object","properties":{"event_id":{"type":"integer"}},"required":["event_id"]}},
    {"name":"create_task","description":"Create task","input_schema":{"type":"object","properties":{"title":{"type":"string"},"priority":{"type":"string","enum":["low","medium","high","urgent"],"default":"medium"},"due_date":{"type":"string"},"category":{"type":"string"}},"required":["title"]}},
    {"name":"get_tasks","description":"Get tasks","input_schema":{"type":"object","properties":{"status":{"type":"string","enum":["pending","in_progress","completed","all"]}}}},
    {"name":"complete_task","description":"Complete task","input_schema":{"type":"object","properties":{"task_id":{"type":"integer"}},"required":["task_id"]}},
    {"name":"delete_task","description":"Delete task","input_schema":{"type":"object","properties":{"task_id":{"type":"integer"}},"required":["task_id"]}},
    {"name":"set_reminder","description":"Set reminder","input_schema":{"type":"object","properties":{"title":{"type":"string"},"trigger_time":{"type":"string"},"description":{"type":"string"}},"required":["title","trigger_time"]}},
    {"name":"set_alarm","description":"Set alarm","input_schema":{"type":"object","properties":{"title":{"type":"string"},"trigger_time":{"type":"string"}},"required":["title","trigger_time"]}},
    {"name":"get_reminders","description":"Get reminders","input_schema":{"type":"object","properties":{}}},
    {"name":"cancel_reminder","description":"Cancel reminder","input_schema":{"type":"object","properties":{"reminder_id":{"type":"integer"}},"required":["reminder_id"]}},
]

ai  = anthropic.Anthropic(api_key=API_KEY)
history: list = []

def run_tool(name: str, inp: dict) -> str:
    try:
        if name=="get_current_datetime":
            return json.dumps({"datetime":datetime.now().isoformat()})
        elif name=="get_upcoming_events":
            end=(datetime.utcnow()+timedelta(days=inp.get("days",7))).isoformat()
            rows=db.execute("SELECT * FROM events WHERE start_time>=datetime('now') AND start_time<=? ORDER BY start_time",(end,)).fetchall()
            return json.dumps([dict(r) for r in rows])
        elif name=="create_event":
            db.execute("INSERT INTO events (title,description,start_time,end_time,location) VALUES (?,?,?,?,?)",
                (inp["title"],inp.get("description",""),inp["start_time"],inp.get("end_time"),inp.get("location","")))
            db.commit(); return json.dumps({"success":True})
        elif name=="delete_event":
            db.execute("DELETE FROM events WHERE id=?",(inp["event_id"],)); db.commit(); return json.dumps({"success":True})
        elif name=="create_task":
            db.execute("INSERT INTO tasks (title,priority,due_date,category) VALUES (?,?,?,?)",
                (inp["title"],inp.get("priority","medium"),inp.get("due_date"),inp.get("category")))
            db.commit(); return json.dumps({"success":True})
        elif name=="get_tasks":
            s=inp.get("status"); q="SELECT * FROM tasks"; p=[]
            if s and s!="all": q+=" WHERE status=?"; p.append(s)
            elif not s: q+=" WHERE status IN ('pending','in_progress')"
            return json.dumps([dict(r) for r in db.execute(q+" ORDER BY due_date ASC",p).fetchall()])
        elif name=="complete_task":
            db.execute("UPDATE tasks SET status='completed',completed_at=datetime('now') WHERE id=?",(inp["task_id"],))
            db.commit(); return json.dumps({"success":True})
        elif name=="delete_task":
            db.execute("DELETE FROM tasks WHERE id=?",(inp["task_id"],)); db.commit(); return json.dumps({"success":True})
        elif name in ("set_reminder","set_alarm"):
            rtype="alarm" if name=="set_alarm" else "reminder"
            cur=db.execute("INSERT INTO reminders (title,description,trigger_time,type) VALUES (?,?,?,?)",
                (inp["title"],inp.get("description",""),inp["trigger_time"],rtype))
            db.commit(); schedule_reminder(cur.lastrowid,inp["trigger_time"],inp["title"])
            return json.dumps({"success":True})
        elif name=="get_reminders":
            return json.dumps([dict(r) for r in db.execute("SELECT * FROM reminders WHERE is_active=1 AND is_triggered=0 ORDER BY trigger_time").fetchall()])
        elif name=="cancel_reminder":
            rid=inp["reminder_id"]
            db.execute("UPDATE reminders SET is_active=0 WHERE id=?",(rid,)); db.commit()
            try: scheduler.remove_job(f"r{rid}")
            except: pass
            return json.dumps({"success":True})
        return json.dumps({"error":f"unknown tool {name}"})
    except Exception as e:
        return json.dumps({"error":str(e)})

def chat(message: str) -> str:
    now = datetime.now().strftime("%A %B %d %Y %H:%M")
    history.append({"role":"user","content":f"[Now: {now}]\n\n{message}"})
    while True:
        resp = ai.messages.create(model="claude-sonnet-4-6",max_tokens=4096,system=SYSTEM,tools=TOOLS,messages=history)
        if resp.stop_reason=="end_turn":
            text=next((b.text for b in resp.content if hasattr(b,"text")),"")
            history.append({"role":"assistant","content":resp.content}); return text
        elif resp.stop_reason=="tool_use":
            history.append({"role":"assistant","content":resp.content})
            results=[{"type":"tool_result","tool_use_id":b.id,"content":run_tool(b.name,b.input)} for b in resp.content if b.type=="tool_use"]
            history.append({"role":"user","content":results})
        else: break
    return "Something went wrong, please try again."

HTML = base64.b64decode("").decode("utf-8")
CSS  = base64.b64decode("").decode("utf-8")
JS   = base64.b64decode("").decode("utf-8")

# ── FastAPI ───────────────────────────────────────────────────
app = FastAPI(title="ARIA")

@app.get("/", response_class=HTMLResponse)
async def root(): return HTML

@app.get("/static/style.css")
async def serve_css(): return Response(CSS, media_type="text/css")

@app.get("/static/app.js")
async def serve_js(): return Response(JS, media_type="application/javascript")

@app.websocket("/ws")
async def ws_ep(ws: WebSocket):
    await ws.accept(); active_ws.append(ws)
    try:
        while True:
            d=json.loads(await ws.receive_text())
            if d.get("type")=="chat":
                await ws.send_json({"type":"response","message":chat(d["message"])})
    except WebSocketDisconnect:
        if ws in active_ws: active_ws.remove(ws)

class Msg(BaseModel): message: str
class EventIn(BaseModel):
    title:str; start_time:str; end_time:Optional[str]=None
    description:Optional[str]=""; location:Optional[str]=""; calendar:Optional[str]="local"
class TaskIn(BaseModel):
    title:str; description:Optional[str]=""; priority:Optional[str]="medium"
    due_date:Optional[str]=None; category:Optional[str]=None
class ReminderIn(BaseModel):
    title:str; trigger_time:str; description:Optional[str]=""; reminder_type:Optional[str]="reminder"
class EmailIn(BaseModel):
    to:list; subject:str; body:str; cc:Optional[list]=None

@app.post("/api/chat")
async def api_chat(m:Msg): return {"response":chat(m.message)}
@app.post("/api/chat/clear")
async def clear_chat(): history.clear(); return {"success":True}
@app.get("/api/status")
async def status():
    ev=db.execute("SELECT COUNT(*) FROM events WHERE start_time>=datetime('now')").fetchone()[0]
    tk=db.execute("SELECT COUNT(*) FROM tasks WHERE status IN ('pending','in_progress')").fetchone()[0]
    rm=db.execute("SELECT COUNT(*) FROM reminders WHERE is_active=1 AND is_triggered=0").fetchone()[0]
    nx=db.execute("SELECT * FROM events WHERE start_time>=datetime('now') ORDER BY start_time LIMIT 1").fetchone()
    return {"upcoming_events":ev,"active_tasks":tk,"pending_reminders":rm,"next_event":dict(nx) if nx else None,"urgent_tasks":[]}
@app.get("/api/events")
async def get_events(days:int=7):
    end=(datetime.utcnow()+timedelta(days=days)).isoformat()
    return [dict(r) for r in db.execute("SELECT * FROM events WHERE start_time>=datetime('now') AND start_time<=? ORDER BY start_time",(end,)).fetchall()]
@app.post("/api/events")
async def create_event(e:EventIn):
    db.execute("INSERT INTO events (title,description,start_time,end_time,location,source) VALUES (?,?,?,?,?,?)",
               (e.title,e.description,e.start_time,e.end_time,e.location,e.calendar)); db.commit(); return {"success":True}
@app.delete("/api/events/{eid}")
async def del_event(eid:int):
    db.execute("DELETE FROM events WHERE id=?",(eid,)); db.commit(); return {"success":True}
@app.get("/api/tasks")
async def get_tasks(status:Optional[str]=None):
    q="SELECT * FROM tasks"; p=[]
    if status and status!="all": q+=" WHERE status=?"; p.append(status)
    elif not status: q+=" WHERE status IN ('pending','in_progress')"
    return [dict(r) for r in db.execute(q+" ORDER BY due_date ASC",p).fetchall()]
@app.post("/api/tasks")
async def create_task(t:TaskIn):
    db.execute("INSERT INTO tasks (title,priority,due_date,category) VALUES (?,?,?,?)",
               (t.title,t.priority,t.due_date,t.category)); db.commit(); return {"success":True}
@app.patch("/api/tasks/{tid}/complete")
async def done_task(tid:int):
    db.execute("UPDATE tasks SET status='completed',completed_at=datetime('now') WHERE id=?",(tid,)); db.commit(); return {"success":True}
@app.delete("/api/tasks/{tid}")
async def del_task(tid:int):
    db.execute("DELETE FROM tasks WHERE id=?",(tid,)); db.commit(); return {"success":True}
@app.get("/api/reminders")
async def get_reminders():
    return [dict(r) for r in db.execute("SELECT * FROM reminders WHERE is_active=1 AND is_triggered=0 ORDER BY trigger_time").fetchall()]
@app.post("/api/reminders")
async def create_reminder(r:ReminderIn):
    rtype="alarm" if r.reminder_type=="alarm" else "reminder"
    cur=db.execute("INSERT INTO reminders (title,description,trigger_time,type) VALUES (?,?,?,?)",
                   (r.title,r.description,r.trigger_time,rtype)); db.commit()
    schedule_reminder(cur.lastrowid,r.trigger_time,r.title); return {"success":True}
@app.delete("/api/reminders/{rid}")
async def del_reminder(rid:int):
    db.execute("UPDATE reminders SET is_active=0 WHERE id=?",(rid,)); db.commit()
    try: scheduler.remove_job(f"r{rid}")
    except: pass
    return {"success":True}
@app.get("/api/emails")
async def get_emails(): return []
@app.post("/api/emails/send")
async def send_email(e:EmailIn): return {"success":False,"error":"Configure Microsoft Graph in .env to enable email"}

if __name__=="__main__":
    print(f"\n  ARIA — Personal Assistant")
    print(f"  Open http://localhost:{PORT} in your browser\n")
    uvicorn.run(app,host=HOST,port=PORT,log_level="warning")
